DO $$
DECLARE
  rec RECORD;
  cur_status VARCHAR(20);
  cur_program INT;
BEGIN
  FOR rec IN SELECT * FROM cohort_enrollment_requests ORDER BY request_id LOOP
    SELECT enrollment_status, program_id INTO cur_status, cur_program
    FROM cohort_enrollments
    WHERE patient_id = rec.patient_id;

    IF rec.request_type = 'ENROLL' AND cur_status = 'INACTIVE' THEN
      UPDATE cohort_enrollments
      SET enrollment_status = 'ACTIVE', program_id = rec.program_id
      WHERE patient_id = rec.patient_id;
    ELSIF rec.request_type = 'TRANSFER' AND cur_status = 'ACTIVE' THEN
      UPDATE cohort_enrollments
      SET program_id = rec.program_id
      WHERE patient_id = rec.patient_id;
    ELSIF rec.request_type = 'DISCHARGE' AND cur_status = 'ACTIVE' AND cur_program = rec.program_id THEN
      UPDATE cohort_enrollments
      SET enrollment_status = 'INACTIVE', program_id = NULL
      WHERE patient_id = rec.patient_id;
    END IF;
  END LOOP;
END $$;

SELECT * FROM cohort_enrollments ORDER BY patient_id;
